1	package org.springframework.samples.petclinic.service;
2	
3	import org.springframework.http.HttpStatus;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.web.bind.annotation.ResponseStatus;
6	
7	/**
8	 * Business rule: two owners must not share a household by accident. On creation an owner is
9	 * rejected when another owner already has the same last name and address, compared
10	 * case-insensitively after collapsing runs of whitespace. The caller may opt in to sharing a
11	 * household ({@code sharesHousehold == true}), which skips the check. Kept as a small,
12	 * self-contained unit so the rule can be enforced from the create flow without adding
13	 * complexity to the controller or service.
14	 */
15	public final class OwnerHouseholdPolicy {
16	
17	    private OwnerHouseholdPolicy() {
18	    }
19	
20	    /**
21	     * Reject the given owner if another existing owner has the same last name and address,
22	     * unless the request explicitly opted in to sharing a household.
23	     *
24	     * @param clinicService   source of the existing owners
25	     * @param owner           the owner being created
26	     * @param sharesHousehold whether the request opted in to a shared household
27	     * @throws DuplicateHouseholdException if the household already exists and sharing was not opted in
28	     */
29	    public static void rejectDuplicateHousehold(ClinicService clinicService, Owner owner, Boolean sharesHousehold) {
30	        if (Boolean.TRUE.equals(sharesHousehold)) {
31	            return;
32	        }
33	        String lastName = normalize(owner.getLastName());
34	        String address = normalize(owner.getAddress());
35	        for (Owner existing : clinicService.findAllOwners()) {
36	            if (!existing.getId().equals(owner.getId())
37	                && lastName.equals(normalize(existing.getLastName()))
38	                && address.equals(normalize(existing.getAddress()))) {
39	                throw new DuplicateHouseholdException();
40	            }
41	        }
42	    }
43	
44	    private static String normalize(String value) {
45	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
46	    }
47	
48	    /** Thrown when another owner already shares the same last name and address. */
49	    @ResponseStatus(HttpStatus.CONFLICT)
50	    public static class DuplicateHouseholdException extends RuntimeException {
51	    }
52	}
53

1	package org.springframework.samples.petclinic.service;
2	
3	import org.springframework.http.HttpStatus;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.web.bind.annotation.ResponseStatus;
6	
7	/**
8	 * Business rule: an owner's telephone must be unique across all owners once normalized
9	 * (non-digit characters removed). Kept as a small, self-contained unit so the rule can be
10	 * enforced from the create flow without adding complexity to the controller or service.
11	 *
12	 * @author Vitaliy Fedoriv
13	 */
14	public final class OwnerTelephonePolicy {
15	
16	    private OwnerTelephonePolicy() {
17	    }
18	
19	    /**
20	     * Reject the given owner if its normalized telephone matches any other existing owner.
21	     *
22	     * @param clinicService source of the existing owners
23	     * @param owner         the owner being created
24	     * @throws DuplicateTelephoneException if the normalized telephone is already in use
25	     */
26	    public static void rejectDuplicateTelephone(ClinicService clinicService, Owner owner) {
27	        String normalized = normalize(owner.getTelephone());
28	        if (normalized.isEmpty()) {
29	            return;
30	        }
31	        for (Owner existing : clinicService.findAllOwners()) {
32	            if (!existing.getId().equals(owner.getId()) && normalized.equals(normalize(existing.getTelephone()))) {
33	                throw new DuplicateTelephoneException();
34	            }
35	        }
36	    }
37	
38	    private static String normalize(String telephone) {
39	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
40	    }
41	
42	    /** Thrown when an owner's normalized telephone is already used by another owner. */
43	    @ResponseStatus(HttpStatus.CONFLICT)
44	    public static class DuplicateTelephoneException extends RuntimeException {
45	    }
46	}
