12	    /**
13	     * Normalize {@code telephone} to E.164: keep an explicit leading '+' and its country
14	     * code when present, otherwise assume '+61' and drop a single leading '0' from the
15	     * national digits. Spaces, dashes and brackets are stripped. The result is returned
16	     * only when it holds 8 to 15 digits after the '+', so an unconvertible number stays
17	     * as its cleaned form and is rejected by validation.
18	     */
19	    static String toE164(String telephone) {
20	        if (telephone == null) {
21	            return null;
22	        }
23	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
24	        String digits;
25	        if (cleaned.startsWith("+")) {
26	            digits = cleaned.substring(1);
27	        }
28	        else {
29	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
30	            digits = "61" + national;
31	        }
32	        if (!digits.matches("[0-9]{8,15}")) {
33	            return cleaned;
34	        }
35	        return "+" + digits;
36	    }
